-- mod-individual-progression: dungeon/raid map -> stage, final boss -> next stage.
-- Generated by LegionToolsServer/progression-data.js from JournalTierXInstance + Map.db2 (7.3.5.26365).
CREATE TABLE IF NOT EXISTS `individual_progression_map` (
  `map_id` INT UNSIGNED NOT NULL,
  `stage` TINYINT UNSIGNED NOT NULL,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`map_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `individual_progression_boss` (
  `creature_entry` INT UNSIGNED NOT NULL,
  `stage` TINYINT UNSIGNED NOT NULL COMMENT 'stage reached after the kill',
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`creature_entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `individual_progression_map`;

DELETE FROM `individual_progression_boss`;
